/**
 * 명리(命理) 한·중·일 용어와 근거를 함께 보존한 구조화 지식 모듈.
 *
 * 정본 데이터는 data/knowledge/myeongri-vault-trilingual.json과
 * data/knowledge/myeongri-trilingual-glossary.json에 있다. 36개 영역의 777개
 * 사실을 런타임 파일 읽기 없이 조회할 수 있도록 TS 상수로 포함한다.
 *
 * 한·중·일 전통은 용어와 체계가 갈릴 수 있다. 각 항목은 한국어, 한자,
 * 중국어, 일본어 토큰과 유파·출처·해석 경계를 함께 보존한다.
 */

export interface MyeongriTrilingualFact {
  /** 명리 용어(한글 표기). */
  termKr: string;
  /** 한자 정자(한중일 공유 표기). */
  hanja: string;
  /** 현대 중국 명리(子平/八字/盲派) 용어. */
  cnTerm: string;
  /** 중국어 병음(성조). */
  cnPinyin: string;
  /** 일본 四柱推命 용어(통변성 체계). */
  jpTerm: string;
  /** 일본어 가나 읽기. */
  jpReading: string;
  /** 개념 정의(전문가 단정체). */
  definition: string;
  /** 명리학적 해석 — 어떻게 읽는가(경향성). */
  interpretation: string;
  /** 콘텐츠 적용 — 독자 자기대입 포인트. */
  application: string;
  /** 합충생극 등 관계. */
  relations: string;
  /** 학파(자평통설/맹파/일본/공통). */
  school: string;
  /** 출처(고전 또는 표준통설). */
  source: string;
  /** 오용 방지 가드 한줄. */
  safety: string;
  /** VAULT 14개 영역(area) 중 출처. */
  area: MyeongriArea;
}

