/** 한국어·한자·중국어·일본어 토큰에서 부분 일치하는 지식 항목을 찾는다. */
export function lookupMyeongriTerm(query: string, limit = 5): MyeongriTrilingualFact[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const hit = (f: MyeongriTrilingualFact) =>
    [f.termKr, f.hanja, f.cnTerm, f.cnPinyin, f.jpTerm, f.jpReading].some((t) =>
      t.toLowerCase().includes(q)
    );
  return MYEONGRI_TRILINGUAL_FACTS.filter(hit).slice(0, limit);
}


